type Ticket={id:number;title:string;status:"OPEN"|"CLOSED"};
type RowProps={ticket:Ticket;onSelect:(id:number)=>void;onClose:(id:number)=>void};
export function TicketRow({ticket,onSelect,onClose}:RowProps){return <tr onClick={()=>onSelect(ticket.id)}><td>{ticket.id}</td><td><button type="button" onClick={event=>{event.stopPropagation();onSelect(ticket.id);}}>{ticket.title}</button></td><td><button type="button" disabled={ticket.status==="CLOSED"} onClick={event=>{event.stopPropagation();onClose(ticket.id);}}>Zamknij</button></td></tr>;}

